60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
67	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
