90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        validateRequiredFields(ownerFieldsDto);
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        rejectDuplicateHousehold(owner, ownerFieldsDto.getSharesHousehold());
122	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
123	        rejectDuplicateTelephone(telephone);
124	        owner.setTelephone(telephone);
125	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
126	        if (owner.getRegistrationDate() == null) {
127	            owner.setRegistrationDate(LocalDate.now());
128	        }
129	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * Builds the next customer code, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
139	     * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
140	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
141	     *
142	     * @param lastName the owner's last name
143	     * @return the assigned customer code
144	     */
145	    private String nextCustomerCode(String lastName) {
146	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
147	        int sequence = this.clinicService.findAllOwners().size() + 1;
148	        return String.format("%s-%04d", last3, sequence);
149	    }
150	
151	    /**
152	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
153	     * offending field so the client learns about all of them at once.
154	     *
155	     * @param ownerFieldsDto the submitted owner fields
156	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
157	     *                                     missing or blank
158	     */
159	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
160	        List<String> errors = new ArrayList<>();
161	        if (isBlank(ownerFieldsDto.getFirstName())) {
162	            errors.add("firstName");
163	        }
164	        if (isBlank(ownerFieldsDto.getLastName())) {
165	            errors.add("lastName");
166	        }
167	        if (isBlank(ownerFieldsDto.getAddress())) {
168	            errors.add("address");
169	        }
170	        if (isBlank(ownerFieldsDto.getCity())) {
171	            errors.add("city");
172	        }
173	        if (isBlank(ownerFieldsDto.getTelephone())) {
174	            errors.add("telephone");
175	        }
176	        if (!errors.isEmpty()) {
177	            throw new MissingOwnerFieldsException(errors);
178	        }
179	    }
180	
181	    private boolean isBlank(String value) {
182	        return value == null || value.isBlank();
183	    }
184	
185	    /**
186	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
187	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
188	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
189	     * followed by 8 to 15 digits.
190	     *
191	     * @param telephone the raw telephone value as submitted
192	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
193	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
194	     */
195	    private String normalizeTelephone(String telephone) {
196	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
197	        String nationalSignificantNumber;
198	        if (cleaned.startsWith("+")) {
199	            nationalSignificantNumber = cleaned.substring(1);
200	        } else {
201	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
202	            nationalSignificantNumber = "61" + national;
203	        }
204	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
205	            throw new InvalidTelephoneException(telephone);
206	        }
207	        return "+" + nationalSignificantNumber;
208	    }
209	
210	    /**
211	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
212	     * value is treated as absent and returns {@code null}); when present the value must be a
213	     * syntactically valid address, and is stored and returned lower-cased.
214	     *
215	     * @param email the raw email value as submitted, may be {@code null}
216	     * @return the lower-cased email, or {@code null} when none was supplied
217	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
218	     */
219	    private String normalizeEmail(String email) {
220	        if (email == null || email.isBlank()) {
221	            return null;
222	        }
223	        String normalized = email.trim().toLowerCase();
224	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
225	            throw new InvalidEmailException(email);
226	        }
227	        return normalized;
228	    }
229	
230	    /**
231	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
232	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
233	     * comparison, so numbers that differ only in formatting still count as duplicates.
234	     *
235	     * @param e164Telephone the E.164 telephone of the owner being created
236	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
237	     */
238	    private void rejectDuplicateTelephone(String e164Telephone) {
239	        boolean inUse = this.clinicService.findAllOwners().stream()
240	            .map(Owner::getTelephone)
241	            .filter(existing -> existing != null)
242	            .map(this::toComparableTelephone)
243	            .filter(existing -> existing != null)
244	            .anyMatch(e164Telephone::equals);
245	        if (inUse) {
246	            throw new DuplicateTelephoneException(e164Telephone);
247	        }
248	    }
249	
250	    /**
251	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
252	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
253	     * than aborting the whole create.
254	     */
255	    private String toComparableTelephone(String telephone) {
256	        try {
257	            return normalizeTelephone(telephone);
258	        } catch (InvalidTelephoneException ex) {
259	            return null;
260	        }
261	    }
262	
263	    /**
264	     * Rejects an owner who lives in the same household as an existing owner, i.e. one whose
265	     * lastName and address both match an existing owner when compared case-insensitively with
266	     * runs of whitespace collapsed to a single space. The request may deliberately opt in to
267	     * sharing a household by setting {@code sharesHousehold=true}, in which case the create is
268	     * allowed to proceed.
269	     *
270	     * @param owner            the owner being created
271	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
272	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
273	     *                                     the request did not opt in with {@code sharesHousehold=true}
274	     */
275	    private void rejectDuplicateHousehold(Owner owner, Boolean sharesHousehold) {
276	        if (Boolean.TRUE.equals(sharesHousehold)) {
277	            return;
278	        }
279	        String lastNameKey = toHouseholdKey(owner.getLastName());
280	        String addressKey = toHouseholdKey(owner.getAddress());
281	        boolean clash = this.clinicService.findAllOwners().stream()
282	            .anyMatch(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
283	                && toHouseholdKey(existing.getAddress()).equals(addressKey));
284	        if (clash) {
285	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
286	        }
287	    }
288	
289	    /**
290	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
291	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
292	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
293	     * string.
294	     */
295	    private String toHouseholdKey(String value) {
296	        if (value == null) {
297	            return "";
298	        }
299	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
300	    }
301	
302	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
303	    @Override
304	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
305	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
306	        if (currentOwner == null) {
307	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
308	        }
309	        currentOwner.setAddress(ownerFieldsDto.getAddress());
310	        currentOwner.setCity(ownerFieldsDto.getCity());
311	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
312	        currentOwner.setLastName(ownerFieldsDto.getLastName());
313	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
314	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
315	        this.clinicService.saveOwner(currentOwner);
316	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Transactional
321	    @Override
322	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
323	        Owner owner = this.clinicService.findOwnerById(ownerId);
324	        if (owner == null) {
325	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
326	        }
327	        this.clinicService.deleteOwner(owner);
328	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
329	    }
330	
331	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
332	    @Override
333	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
334	        Owner owner = this.clinicService.findOwnerById(ownerId);
335	        if (owner == null) {
336	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
337	        }
338	        HttpHeaders headers = new HttpHeaders();
339	        Pet pet = petMapper.toPet(petFieldsDto);
340	        owner.setId(ownerId);
341	        pet.setOwner(owner);
342	        pet.getType().setName(null);
343	        this.clinicService.savePet(pet);
344	        PetDto petDto = petMapper.toPetDto(pet);
345	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
346	            .buildAndExpand(pet.getId()).toUri());
347	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
348	    }
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
353	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
354	        if (currentOwner != null) {
355	            Pet currentPet = this.clinicService.findPetById(petId);
356	            if (currentPet != null) {
357	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
358	                currentPet.setName(petFieldsDto.getName());
359	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
360	                this.clinicService.savePet(currentPet);
361	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
362	            }
363	        }
364	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
365	    }
366	
367	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
368	    @Override
369	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
370	        HttpHeaders headers = new HttpHeaders();
371	        Visit visit = visitMapper.toVisit(visitFieldsDto);
372	        Pet pet = new Pet();
373	        pet.setId(petId);
374	        visit.setPet(pet);
375	        this.clinicService.saveVisit(visit);
376	        VisitDto visitDto = visitMapper.toVisitDto(visit);
377	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
378	            .buildAndExpand(visit.getId()).toUri());
379	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
380	    }
381	
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Override
385	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
386	        Owner owner = this.clinicService.findOwnerById(ownerId);
387	        if (owner != null) {
388	            Pet pet = owner.getPet(petId);
389	            if (pet != null) {
390	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
391	            }
392	        }
393	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
394	    }
395	}
